0,"Create a code snippet that deals with font management in a desktop application. The code should verify if a font file is loaded, and if not, load it and set it to null. Then, it should determine if a default font directory is set, and if not, set it to a predefined default value. Finally, it should extract the font data from the system directory and store it in a font cache.",276,,"['This task involves using classes like `Font` for loading and managing fonts and also file handling, so here's a simple pseudo-code of how you might write this:

```python
import os
from java.awt import Font
from java.util import HashMap

class FontManager:
    def __init__(self):
        self.loaded_fonts = {}
        self.default_font_directory = None

    def is_font_loaded(self, font_name):
        if font_name in self.loaded_fonts:
            return True
        else:
            return False

    def load_font(self, font_path):
        try:
            font = Font.createFont(Font.TRUETYPE_FONT, new FileInputStream(new File(font_path)))
            self.loaded_fonts[font_name] = font
            return True
        except Exception as e:
            print(""Error loading font: "", str(e))
            return False

    def set_default_directory(self, directory):
        if os.path.isdir(directory):
            self.default_font_directory = directory
        else:
            print(""Directory does not exist."")

    def extract_system_fonts(self):
        system_font_cache = HashMap<>() # Use HashMap here because it's a Java environment
        if self.default_font_directory is None:
            print(""Default font directory has not been set"")
            return

        for root, dirs, files in os.walk(self.default_font_directory):
            for file in files:
                if file.endswith('.ttf') or file.endswith('.otf'): # Only consider .ttf and .otf font files
                    full_path = os.path.join(root, file)
                    system_font_cache[file] = full_path  # This will only store the path to the font file
        return system_font_cache
```

