import json
from typing import Optional, Union

def loadJsonObjectFromFile(file_path: str) -> Union[Optional[dict], str]:
    try:
        with open(file_path, 'r') as file:
            return json.load(file)
    except FileNotFoundError:
        return None, ""Error: File not found.""
    except PermissionError:
        return None, ""Error: Insufficient permissions to read the file.""
    except IsADirectoryError:
        return None, ""Error: Path is a directory and not a file.""
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None, ""Error: File is not in JSON format.""
```

