```python
import json
from typing import Callable

class JsonFactoryBase:
    _registry = {}

    def __init__(self, id):
        self.id = id

    @staticmethod
    def create_instance(json_string):
        data = json.loads(json_string)
        if 'id' in data and data['id'] in JsonFactoryBase._registry:
            return JsonFactoryBase._registry[data['id']](json_string)
        else:
            raise ValueError(""Unknown or missing ID"")

    @staticmethod
    def register(id, factory_func):
        if isinstance(factory_func, Callable):
            JsonFactoryBase._registry[id] = factory_func
        else:
            raise TypeError(""factory_func must be a callable"")

    def to_json(self):
        return json.dumps(self.__dict__)

class MyJsonClass(JsonFactoryBase):
    def __init__(self, id, name, value):
        super().__init__(id)
        self.name = name
        self.value = value

def factory_func(json_string):
    data = json.loads(json_string)
    return MyJsonClass(data['id'], data['name'], data['value'])

# Register the class with its factory function
JsonFactoryBase.register('myclass', factory_func)

# Create a new instance from JSON string using factory function associated with 'myclass' ID
json_string = json.dumps({""id"": ""myclass"", ""name"": ""test"", ""value"": 1})
new_instance = JsonFactoryBase.create_instance(json_string)
print(new_instance.__dict__)  # Output: {'id': 'myclass', 'name': 'test', 'value': 1}
```
