# JWT authentication decorator
def require_jwt(view_function):
    @wraps(view_function)
    def decorated_function(*args, **kwargs):
        auth_header = request.headers.get('Authorization')

        if not auth_header or 'Bearer' not in auth_header:
            return jsonify({""error"": ""Missing Authorization Header.""}), 401

        try:
            token = auth_header.split("" "")[1]
            decoded_token = jwt.decode(token, SECRET_KEY)
        except:
            return jsonify({""error"": ""Invalid or Expired Token.""}), 401

        g.user = decoded_token['sub']  # user from token payload

        return view_function(*args, **kwargs)
    return decorated_function

@app.route('/api/records', methods=['POST'])
@rate_limited()
@require_jwt
def add_record():
    data = request.get_json()  # assuming the record is sent as json in body
    try:
        with sqlite3.connect(DATABASE) as conn:
            cur = conn.cursor()
            query = 'INSERT INTO records (data) VALUES (?)'
            cur.execute(query, data)
            conn.commit()

        return jsonify({""message"": ""Record added successfully.""}), 201
    except Exception as e:
        return jsonify({""error"": str(e)}), 500

# other endpoints (GET, PUT, DELETE) are implemented in a similar way
