import csv
import pandas as pd

def enhanced_csv_processor(input_path, output_path, criteria):
    try:
        # Read CSV file into DataFrame
        df = pd.read_csv(input_path)

        # Apply processing criteria
        if 'filter' in criteria:
            filtered_df = df[criteria['filter']]
        else:
            filtered_df = df.copy()

        if 'transform' in criteria:
            for col, func in criteria['transform'].items():
                filtered_df[col] = filtered_df[col].apply(func)

        # Output processed data to new CSV file
        if not output_path.endswith('.csv'):
            output_path += '.csv'

        with open(output_path, 'w', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(filtered_df.columns.tolist())

            for index, row in filtered_df.iterrows():
                writer.writerow(row.tolist())

    except FileNotFoundError:
        print(""File not found. Please check the input path and try again."")
    except Exception as e:
        print(f""An error occurred: {e}"")
