from collections import deque
import re
import os

class FileNameManager:
    def __init__(self):
        self.fileNames = deque()

    @staticmethod
    def validateExtension(filename, default='.txt'):
        if '.' not in filename:
            return filename + default
        else:
            return filename

    @staticmethod
    def splitFilenameIntoParts(filename):
        parts = re.split('\.', filename)
        name, extension = ''.join(parts[:-1]), parts[-1]
        return name, extension

    def addFileName(self, filename, sortKey='name'):
        validatedFilename = self.validateExtension(filename)
        if sortKey == 'name':
            for i in range(len(self.fileNames)):
                if self.splitFilenameIntoParts(validatedFilename)[0] < self.splitFilenameIntoParts(self.fileNames[i])[0]:
                    self.fileNames.insert(i, validatedFilename)
                    return 
            self.fileNames.append(validatedFilename)
        elif sortKey == 'date':
            # In a real implementation we would add code to get the date of creation of each file and sort accordingly
