    def processFilename(self, criteria):
        for filename in self.fileNames:
            if criteria in filename:
                name, extension = self.splitFilenameIntoParts(filename)
                new_extension = input(""Enter the new file extension: "")
                os.rename(filename, name + '.' + new_extension)

