import random
from datetime import datetime, timedelta
from PIL import Image
import os

class TemperatureReading:
    def __init__(self, timestamp, location_id, temperature):
        self.timestamp = timestamp
        self.location_id = location_id
        self.temperature = temperature

def generate_temperature_readings(num_readings):
    timestamps = [datetime.now() + timedelta(minutes=random.randint(0, 60)) for _ in range(num_readings)]
    locations = ['Location' + str(i) for i in range(1, num_readings + 1)]
    temperatures = [random.uniform(-50.0, 50.0) for _ in range(num_readings)]

    readings = []
    for timestamp, location_id, temp in zip(timestamps, locations, temperatures):
        reading = TemperatureReading(timestamp=timestamp, location_id=location_id, temperature=temp)
        readings.append(reading)

    return readings

def process_tiff_image(file_path):
    try:
        img = Image.open(file_path)
        if img.format.lower() == 'tiff':
            info = img.info.get('dpi')
            bits_per_sample = img.info.get('bits_per_sample')
            samples_per_pixel = img.info.get('samples_per_pixel')

            if bits_per_sample == 8 and samples_per_pixel == 1:
                print(""This TIFF image is suitable for further processing."")

            else:
                print(""This TIFF image may require additional adjustments."")
        else:
            print(""The provided file is not a TIFF image."")

    except Exception as e:
        print(f""An error occurred while processing the TIFF image: {e}"")

def process_directory_for_tiff_images(directory_path):
    if not os.path.exists(directory_path):
        raise FileNotFoundError(f""The directory '{directory_path}' does not exist."")

    num_processed_files = 0
    num_unsupported_files = 0

    for root, dirs, files in os.walk(directory_path):
        for file_name in files:
            file_path = os.path.join(root, file_name)

            if file_name.lower().endswith('.tiff'):
                process_tiff_image(file_path)
                num_processed_files += 1

    print(f""Processed {num_processed_files} TIFF images."")
    print(f""{num_unsupported_files} files were not supported."")
