```python
import websockets
import zlib
from websockets import WebSocketClientProtocol
from typing import Optional

class CompressedWebSocketClient(object):
    def __init__(self, uri: str, compress: bool = True):
        self.uri = uri
        self.compress = compress
        self._conn = None  # type: Optional[WebSocketClientProtocol]

    async def connect(self):
        if not self._conn:
            self._conn = await websockets.connect(self.uri)

    def send(self, message: str):
        if self._conn and self.compress:
            compressed_message = zlib.compress(bytes(message, 'utf-8'))
            self._conn.send(compressed_message)
        elif self._conn:
            self._conn.send(message)

    def receive(self):
        if self._conn and self.compress:
            compressed_response = yield from self._conn.recv()
            return zlib.decompress(compressed_response).decode('utf-8')
        elif self._conn:
            return (yield from self._conn.recv())
```

This class creates a WebSocket client with support for frame compression/decompression based on the `compress` argument in its constructor. The `connect()` method establishes the connection, and `send()` sends a message to the server (with optional compression) and `receive()` waits and returns a message from the server (with decompression).
