This integration not only secures OAuth2 access tokens with DES encryption but also ensures their integrity through rigorous testing with random number generation within specified constraints. The system elegantly combines data validation with cryptographic protection mechanisms while leveraging modern mocking techniques for robust verification processes.",347,,"[""Here is a Python-like pseudo code that follows the description you provided. Please note, you will need to install 'pyOpenSSL', 'blueslip' and 'mock' python libraries first.

```python
import json
from OpenSSL import crypto
import mock
from blueslip import Blueslip

class TokenEncryptor:
    def __init__(self, token_json):
        self.token = json.loads(token_json)

    def validate(self):
        required_fields = ['access_token', 'expires_in', 'token_type']
        if all(field in self.token for field in required_fields):
            if (self.token['token_type'] == 'Bearer') and (300 <= self.token['expires_in'] <= 3600):
                return True
        return False

    def encrypt(self):
        if not self.validate():
            raise ValueError('Invalid token for encryption.')

        des = crypto.DES.new('12345678', crypto.DES.MODE_ECB)  # '12345678' is the key
        return des.encrypt(self.token['access_token'])

class MockTestRunner:
    def __init__(self):
        self._blueslip = Blueslip()

    def run_test(self, test_function):
        mocked_numbers = [self.get_random_number() for _ in range(10)]  # Replace with actual API call or data exchange

        self._blueslip.mock(
            'your_module.TokenEncryptor',
            'validate',
            lambda *args, **kwargs: mocked_numbers[self._index] > 0.5  # Replace with actual criteria for validity
        )

        test_function()

    def get_random_number(self):
        return self._blueslip.mock('random.uniform', lambda a, b: (a + b) / 2)
```
