```python
from flask import Flask, jsonify, request
from werkzeug.security import generate_password_hash, check_password_hash
from flask_sqlalchemy import SQLAlchemy
from flask_jwt_extended import (JWTManager, jwt_required, create_access_token)
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
import sqlite3

app = Flask(__name__)

# Set up SQLAlchemy
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)
limiter = Limiter(app, key_func=get_remote_address)
jwt = JWTManager(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)

@app.route('/signup', methods=['POST'])
def signup():
    data = request.get_json()
    hashed_password = generate_password_hash(data['password'], method='sha256')
    new_user = User(username=data['username'], password=hashed_password)
    db.session.add(new_user)
    db.session.commit()

    return jsonify({'message': 'New user created!'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    current_user = User.query.filter_by(username=data['username']).first()

    if not current_user:
        return jsonify({'message': 'User does not exist!'}), 401

    if check_password_hash(current_user.password, data['password']):
        access_token = create_access_token(identity=data['username'])
        return jsonify(access_token=access_token), 200

    else:
        return jsonify({'message': 'Wrong password!'}), 401

@app.route('/user', methods=['GET', 'PUT', 'DELETE'])
@jwt_required()
def user():
    current_user = User.query.filter_by(username=current_identity).first()

    if request.method == 'GET':
        return jsonify({'id': current_user.id, 'username': current_user.username})

    elif request.method == 'PUT':
        data = request.get_json()
        hashed_password = generate_password_hash(data['new_password'], method='sha256')
        current_user.password = hashed_password
        db.session.commit()

        return jsonify({'message': 'Password updated!'})

    elif request.method == 'DELETE':
        db.session.delete(current_user)
        db.session.commit()

        return jsonify({'message': 'User deleted!'}), 204

@app.errorhandler(429)
def ratelimit_handler(e):
    return jsonify({'error': ""ratelimit exceeded %s"" % e.description})

if __name__ == '__main__':
    app.run(debug=True)
