        command_futures = {executor.submit(run_command_in_background, cmd): cmd for cmd in commands_list}
        for future in concurrent.futures.as_completed(command_futures):
            command = command_futures[future]
            try:
                stdout, stderr = future.result()
                print(f""Command: {command} Output: {stdout.decode().strip()}, Error: {stderr.decode().strip()}"")
            except Exception as e:
                print(f""Command: {command} Execution failed with error: {e}"")

