```python
import random
import networkx as nx
from scipy import stats
import logging
import pandas as pd

class GraphGenerator:
    def __init__(self, probability_map):
        self.probability_map = probability_map
        self.G = nx.Graph()
        self.logger = logging.getLogger(__name__)

    def add_vertices(self, vertex_type):
        for key in self.probability_map:
            if random.random() < self.probability_map[key]:
                self.G.add_node(vertex_type())

    def add_edges(self, edge_type, probability, vertex_list):
        for node1 in self.G.nodes:
            for node2 in vertex_list:
                if random.random() < probability and node1 != node2:
                    self.G.add_edge(node1, node2, type=edge_type())

    def set_properties(self, properties):
        for node in self.G.nodes():
            for prop in properties:
                self.G.nodes[node][prop] = properties[prop]()

    def add_weighted_edges(self, weight_distribution, edge_list):
        for edge in edge_list:
            self.G[edge[0]][edge[1]]['weight'] = weight_distribution.rvs()

    def calculate_centrality(self, centrality_measure):
        return centrality_measure(self.G)

    def remove_randomly(self, probability):
        for node in self.G.nodes():
            if random.random() < probability:
                self.G.remove_node(node)

    def calculate_clustering(self):
        return nx.clustering(self.G)

    def import_data(self, filepath):
        df = pd.read_csv(filepath)
        for index, row in df.iterrows():
            self.G.add_node(row['vertex'], type=row['type'])

if __name__ == ""__main__"":
    logging.basicConfig(level=logging.INFO)

    # Define probability map
    prob_map = {""person"": 0.5, ""location"": 0.3, ""organization"": 0.2}

    # Initialize GraphGenerator with the defined probability map
    generator = GraphGenerator(prob_map)

    # Add vertices of different types as per the probabilities defined in prob_map
    for vertex_type in [""person"", ""location"", ""organization""]:
        generator.add_vertices(vertex_type)

    # You would need to define methods to generate random vertex types and edge types 
    # And also define a method for generating properties for vertices/edges
```
