```python
import hashlib
from xml.etree import ElementTree as ET

class CharacterAttackSelector:
    def __init__(self):
        self.attacks = ['Sonic Boom', 'Fireball']

    def ExecuteAttack(self, attack_name, slash=False):
        if slash:
            print(f""{attack_name} with slashes!!"")
        else:
            print(f""{attack_name} without slashes."")

    def SlashedAttackName(self, xml_file):
        tree = ET.parse(xml_file)
        root = tree.getroot()

        for attack in self.attacks:
            node = root.find(f"".//action[@name='{attack}']"")

            if node is not None and node.attrib['slash'] == 'true':
                self.ExecuteAttack(node.text, True)
            else:
                self.ExecuteAttack(node.text, False)

    def HashedAttackName(self, text):
        hashed_string = hashlib.sha256(text.encode()).hexdigest()

        for attack in self.attacks:
            if attack in hashed_string:
                self.ExecuteAttack(attack)
```
