def read_configuration_file(config_file_path: str) -> Dict[str, List[Tuple[str, str]]]:
    sections = {}
    current_section = None
    with open(config_file_path, 'r') as file:
        for line in file:
            if '#' in line or not line.strip():
                continue

            if '[' in line and ']' in line and '=' not in line:
                current_section = line.strip('[]').strip()
                sections[current_section] = []

            elif '=' in line and current_section is not None:
                key, value = [x.strip() for x in line.split('=', 1)]
                sections[current_section].append((key, value))

    return sections

def save_output(output_lines: List[str], output_dir: str):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    for index, (section_name, lines) in enumerate(sections.items(), start=1):
        section_output_dir = os.path.join(output_dir, section_name)
        if not os.path.exists(section_output_dir):
