```python
import random

class NFAPI_DISCOVERY_RESPONSE_PDU_T(object):
    def __init__(self, tac):
        self.tac = tac

def generate_entities(n, min_tac=0, max_tac=2**16-1):
    if not isinstance(n, int) or n <= 0:
        return ""Error: Invalid number of entities""
    elif not isinstance(min_tac, int) or not isinstance(max_tac, int) or min_tac < 0 or max_tac > 2**16-1:
        return ""Error: Invalid tracking area code range""

    entities = []
    for _ in range(n):
        tac = random.randint(min_tac, max_tac)  # Generate a random TAC within the specified range
        entity = NFAPI_DISCOVERY_RESPONSE_PDU_T(tac)
        entities.append(entity)

    return entities
```
