```python
import os

def validate_filename(name):
    invalid_chars = set('\/:*?""<>|')
    if not name or len(name) > 255 or any((c in invalid_chars) for c in name):
        return False
    else:
        return True

def add_extension(filename, extension, valid_types=None):
    if not validate_filename(filename):
        print(""Invalid filename."")
        return None

    if valid_types and extension not in valid_types:
        print(""Invalid file type."")
        return None

    newname = filename + '.' + extension
    return newname

def format_size(bytes, fmt='gb'):
    if fmt == 'kb':
        size = bytes / 1024
    elif fmt == 'mb':
        size = bytes / (1024 * 1024)
    else:
        size = bytes / (1024 * 1024 * 1024)

    return size

def get_file_size(filename):
    if os.path.exists(filename):
        bytes = os.stat(filename).st_size
        return format_size(bytes, 'gb')  # customizable to mb or kb
    else:
        print(""File not found."")
        return None

def main():
    filename = input(""Enter a file name: "")
    extension = input(""Enter the file extension: "")

    valid_types = ['txt', 'jpg', 'png']  # predefined list of valid types
    newname = add_extension(filename, extension, valid_types)

    if newname is not None:
        print('Renamed file: ', newname)

    size = get_file_size(newname)
    if size is not None:
        print('File size in GB: ', size)

if __name__ == ""__main__"":
    main()
```
This script prompts the user to enter a file name and an extension, checks both for validity, adds the extension (if valid), and prints out the new filename. It also provides functionality to check if a file with that name exists, and if it does, it fetches its size in GB (by default, but customizable). Note: replace 'valid_types' with your own list of acceptable types.
