```",120,,"['Here's how you might solve this problem using Python.

```python
import os
def validate_file_name(file_name, max_length):
    if not file_name:
        return False, ""File name cannot be null""
    if len(file_name) > max_length:
        return False, f""File name exceeds maximum length of {max_length} characters""
    invalid_chars = set('<>:""/\\|?*')
    if any(char in invalid_chars for char in file_name):
        return False, ""File name contains invalid characters""
    return True, """"

def check_file_type(file_type, valid_types):
    if file_type in valid_types:
        return True
    else:
        return False

def format_file_size(file_size):
    if file_size < 1024:
        return f""{file_size} bytes""
    elif 1024 <= file_size < 1024**2:
        kb = file_size / 1024
        return f""{round(kb, 2)} KB""
    elif 1024**2 <= file_size < 1024**3:
        mb = file_size / (1024**2)
        return f""{round(mb, 2)} MB""

def rename_and_add_extension(file_name_input, extension_input, max_length=50, valid_extensions=('txt', 'pdf', 'docx'), custom_message=""Renamed and added extension successfully""):
    valid_name_flag, validation_message = validate_file_name(file_name_input, max_length)
    if not valid_name_flag:
        print(validation_message)
        return  # Return here as any other processing is not required
    else:
        if check_file_type(extension_input.lower(), [extension.lower() for extension in valid_extensions]):
            new_file_name = f""{file_name_input}.{extension_input}""
            print(custom_message)
            print(f""File size: {format_file_size(os.path.getsize(new_file_name))}"")

def main():
    file_name_input = input(""Enter a filename: "")
    extension_input = input(""Enter an extension: "")
    rename_and_add_extension(file_name_input, extension_input)

if __name__ == ""__main__"":
    main()
``` 

