```python
import pandas as pd
from dataclasses import dataclass

@dataclass
class DatabaseInfo:
    path: str
    encoding_format: str

def loadDatabaseFile(database_info: DatabaseInfo):
    try:
        df = pd.read_csv(database_info.path, encoding=database_info.encoding_format)

        if df.isnull().sum().sum() > 0:
            print(""Error: The database file is not valid."")
        else:
            print(""Successfully loaded the database file."")
    except Exception as e:
        print(f""An error occurred while loading the database file: {str(e)}"")
```
