```python
import re
import sys

def read_and_sort_lines(file_path):
    try:
        with open(file_path, ""r"") as f:
            lines = f.read().splitlines()

            if not lines:
                raise ValueError('File is empty')

            return sorted(lines)

    except FileNotFoundError:
        raise FileNotFoundError('No such file or directory')

def extract_sequence_number(sorted_lines):
    try:
        last_line = sorted_lines[-1]
        match = re.match(r""Sequence\s+(\d+)"", last_line)

        if match is None or not match.group(1).isdigit():
            raise ValueError('Sequence number is not numeric')

        return int(match.group(1))

    except IndexError as e:
        print(f'Error extracting sequence number from corrupted format: {e}', file=sys.stderr)
        raise ValueError('Corrupted format')

def process_file(file_path):
    sorted_lines = read_and_sort_lines(file_path)
    return extract_sequence_number(sorted_lines)

def unit_tests():
    test_files = [""test1.txt"", ""test2.txt"", ""test3.txt"", ""test4.txt"", ""test5.txt""]

    for test in test_files:
        try:
            result = process_file(test)
            print(f""Test '{test}' passed. Sequence Number: {result}"")

        except (ValueError, FileNotFoundError) as e:
            print(f'Test ""{test}"" failed. Error Message: {e}')
```
Please note that I added error handling to the `process_file` function which calls `read_and_sort_lines` and `extract_sequence_number` functions to make sure they raise appropriate exceptions when necessary. The `unit_tests` function now uses these new functions and handles exceptions properly.
