```python
import hashlib
from typing import Dict, List

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self):
        self.RX_UE_INFORMATION_TAG = 0x80
        self.RNTI = 123456789
        self.CRC_INDICATION_REL8_TAG = [i for i in range(1, 11)]

    def create_pdu(self):
        return {
            'RX_UE_INFORMATION_TAG': self.RX_UE_INFORMATION_TAG,
            'RNTI': self.RNTI,
            'CRC_INDICATION_REL8_TAG': self.CRC_INDICATION_REL8_TAG
        }

def create_pdu_list(n: int) -> List[Dict]:
    pdus = []
    for _ in range(n):
        pdu = NFAPI_CRC_INDICATION_PDU_T()
        pdus.append(pdu.create_pdu())
    return pdus

def calculate_md5(string: str) -> str:
    return hashlib.md5(str(string).encode('utf-8')).hexdigest()

def generate_crossover(n: int) -> Dict[str, List]:
    pdus = create_pdu_list(n)
    md5s = [calculate_md5(pdu) for pdu in pdus]

    return {
        'pdus': pdus,
        'md5s': md5s
    }
```
