pub struct Task {
    name: String,
    task_func: Box<dyn Fn() -> Result<(), &'static str>>,
}

impl Task {
    pub fn new(name: String, task_func: Box<dyn Fn() -> Result<(), &'static str>>) -> Self {
        Self { name, task_func }
    }

    pub fn execute(&self) -> Result<(), &'static str> {
        (self.task_func)()
    }
}

pub struct TaskManager {
    tasks: HashMap<String, Task>,
    task_order: VecDeque<String>,
    paused: bool,
    tx: Option<mpsc::Sender<Task>>,
}

impl TaskManager {
    pub fn new() -> Self {
        Self {
            tasks: HashMap::new(),
            task_order: VecDeque::new(),
            paused: false,
            tx: None,
        }
    }

    pub fn add_task(&mut self, name: String, task_func: Box<dyn Fn() -> Result<(), &'static str>>) {
        let task = Task::new(name.clone(), task_func)

column7:
}

pub fn execute(&mut self) -> Result<(), &'static str> {
    if self.paused {
        return Ok(())

column8:
    }

    for name in &self.task_order {
        match self.tasks.get(name) {
            Some(task) => match task.execute() {
                Err(e) => return Err(e),
                _ => (),
            },
            None => return Err(""Task not found""),
        }
    }

    Ok(())
}

pub fn pause(&mut self) {
    self.paused = true

