```python
import os, stat
from pathlib import Path

class FilePermissionsManager():
    def __init__(self):
        pass

    def validate_inputs(self, dirPath, permMask, modeMask):
        if not isinstance(dirPath, str) or not Path(dirPath).is_dir():
            raise ValueError(""Invalid directory path"")

        if not isinstance(permMask, int) or permMask > 0o777:
            raise ValueError(""Invalid permission bitmask. It should be an octal number between 0 and 0o777."")

        if not isinstance(modeMask, int) or modeMask > 0x1ff:
            raise ValueError(""Invalid access mode bitmask. It should be a decimal number between 0 and 511."")

    def apply_permissions(self, dirPath, permMask, modeMask):
        self.validate_inputs(dirPath, permMask, modeMask)

        for root, dirs, files in os.walk(dirPath):
            for d in dirs:
                try:
                    os.chmod(os.path.join(root, d), permMask)
                except Exception as e:
                    print(f""Error applying permissions to {os.path.join(root, d)} : {str(e)}"")
            for f in files:
                try:
                    os.chmod(os.path.join(root, f), permMask)
                    if modeMask > 0: # 0 means no change
                        os.chflags(os.path.join(root, f), modeMask)
                except Exception as e:
                    print(f""Error applying permissions to {os.path.join(root, f)} : {str(e)}"")
```

This solution checks input parameters for correctness and range. It then recursively applies the specified file and directory permissions and access modes. Errors during permission application are caught and printed out with descriptive error messages. Note that this code requires a Unix-based system or Windows 10 version 1607 or newer due to the usage of os.chflags for setting file flags.
