import os
import hashlib

def generate_random_bitstream(length):
    random_bytes = os.urandom(length * 8)
    return ''.join(str(bool(byte)) for byte in random_bytes)

def compute_file_md5_with_random_salt(file_path, salt_length=32):
    bitstream = generate_random_bitstream(salt_length)

    full_path = f""{file_path}_{bitstream}""

    with open(full_path, 'rb') as f:
        md5_obj = hashlib.md5()
        for chunk in iter(lambda: f.read(4096), b""""):
            md5_obj.update(chunk)

        return md5_obj.hexdigest()
