class AsyncReducer:
    @staticmethod
    async def reduce(array: list, initialValue: Any, callback: Callable[[Any, Any], Any]):
        result = initialValue
        for element in array:
            try:
                result = await callback(result, element)
            except Exception as e:
                print('Error occurred during reduction: ', str(e))
        return result
