```python
import uuid
from random import randint

def get_public_address():
    # Pseudo-random generation of an IP address
    return ""."".join(map(str, (randint(0, 255) for _ in range(4))))

def get_port_number():
    # Pseudo-random generation of a port number
    return randint(1024, 65535)

def generate_unique_id():
    # Generate a unique identifier using the uuid library
    return str(uuid.uuid4())

def generate_necm_list(num):
    necms = []

    for _ in range(num):
        necms.append({
            'public_address': get_public_address(),
            'port_number': get_port_number(),
            'unique_id': generate_unique_id()
        })

    return necms
```
